        anchor_snapshot: Dict[str, Dict[str, Dict[str, Any]]] = {}
        notice_snapshot: Dict[str, Dict[str, Any]] = {}
        sync_snapshot: Dict[str, Dict[str, Dict[str, Any]]] = {}
