        # UTC 整数秒相减，不使用接收/审计/重放时间刷新。
        updated_dt = _parse_utc_z(row["updated_at"])
        age = int(now.timestamp()) - int(updated_dt.timestamp())  # type: ignore[union-attr]
        if age < 0:
            return False, (
                EXTERNAL_CREDENTIAL_STATUS_CLOCK_AHEAD_REASON
            )
        if age > max_status_age:
            return False, EXTERNAL_CREDENTIAL_STATUS_STALE_REASON
        return True, ""
    if status == "revoked":
        saved_reason = row.get("reason")
        if not saved_reason:
            saved_reason = "未知原因"
        return False, f"外部凭证已吊销：{saved_reason}"
    if status == "suspended":
        saved_reason = row.get("reason")
        if not saved_reason:
            saved_reason = "未知原因"
        return False, f"外部凭证已暂停：{saved_reason}"
    # status 仅可能为 active/revoked/unknown/suspended（同步入口已约束）。
    return False, "外部凭证状态未知"

